import type { NoodlesProjectJSON } from '../utils/serialization'

// Migration to rename DateOp to DateTimeOp
//
// This migration:
// 1. Renames all nodes of type "DateOp" to "DateTimeOp"
//
// Note: Timeline keyframes reference operators by ID (e.g., "/date-1"), not by type,
// so no timeline updates are needed. The operator type change is transparent to the timeline.

export async function up(project: NoodlesProjectJSON): Promise<NoodlesProjectJSON> {
  const { nodes, ...rest } = project

  // Rename node types
  const newNodes = nodes.map(node => {
    if (node.type === 'DateOp') {
      return { ...node, type: 'DateTimeOp' }
    }
    return node
  })

  return {
    ...rest,
    nodes: newNodes,
  }
}

export async function down(project: NoodlesProjectJSON): Promise<NoodlesProjectJSON> {
  const { nodes, ...rest } = project

  // Revert node types
  const newNodes = nodes.map(node => {
    if (node.type === 'DateTimeOp') {
      return { ...node, type: 'DateOp' }
    }
    return node
  })

  return {
    ...rest,
    nodes: newNodes,
  }
}

import { describe, expect, it } from 'vitest'
import type { NoodlesProjectJSON } from '../utils/serialization'
import { down, up } from './013-add-time-markers'

describe('013-add-time-markers migration', () => {
  describe('up', () => {
    it('adds empty markers array to existing timeline sequence', async () => {
      const project: NoodlesProjectJSON = {
        version: 12,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {
          sheetsById: {
            Noodles: {
              sequence: {
                length: 10,
                subUnitsPerUnit: 30,
                tracksByObject: {},
              },
              staticOverrides: { byObject: {} },
            },
          },
        },
      }

      const result = await up(project)

      const sequence = (result.timeline as any).sheetsById.Noodles.sequence
      expect(sequence.markers).toEqual([])
      expect(sequence.length).toBe(10)
      expect(sequence.subUnitsPerUnit).toBe(30)
    })

    it('preserves existing markers if present', async () => {
      const existingMarkers = [
        { id: 'tm_123', position: 2.5, connections: [] },
        {
          id: 'tm_456',
          position: 5.0,
          connections: [{ keyframeId: 'kf_abc', trackPath: 'op / prop', offset: 0.5 }],
        },
      ]

      const project: NoodlesProjectJSON = {
        version: 12,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {
          sheetsById: {
            Noodles: {
              sequence: {
                length: 10,
                subUnitsPerUnit: 30,
                tracksByObject: {},
                markers: existingMarkers,
              },
              staticOverrides: { byObject: {} },
            },
          },
        },
      }

      const result = await up(project)

      const sequence = (result.timeline as any).sheetsById.Noodles.sequence
      expect(sequence.markers).toEqual(existingMarkers)
    })

    it('handles project with no timeline', async () => {
      const project: NoodlesProjectJSON = {
        version: 12,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {},
      }

      const result = await up(project)
      expect(result).toEqual(project)
    })

    it('handles project with no sequence', async () => {
      const project: NoodlesProjectJSON = {
        version: 12,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {
          sheetsById: {
            Noodles: {
              staticOverrides: { byObject: {} },
            },
          },
        },
      }

      const result = await up(project)
      expect(result).toEqual(project)
    })
  })

  describe('down', () => {
    it('removes markers array from timeline sequence', async () => {
      const project: NoodlesProjectJSON = {
        version: 13,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {
          sheetsById: {
            Noodles: {
              sequence: {
                length: 10,
                subUnitsPerUnit: 30,
                tracksByObject: {},
                markers: [{ id: 'tm_123', position: 2.5, connections: [] }],
              },
              staticOverrides: { byObject: {} },
            },
          },
        },
      }

      const result = await down(project)

      const sequence = (result.timeline as any).sheetsById.Noodles.sequence
      expect(sequence.markers).toBeUndefined()
      expect(sequence.length).toBe(10)
      expect(sequence.subUnitsPerUnit).toBe(30)
    })

    it('handles project with no markers', async () => {
      const project: NoodlesProjectJSON = {
        version: 13,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {
          sheetsById: {
            Noodles: {
              sequence: {
                length: 10,
                subUnitsPerUnit: 30,
                tracksByObject: {},
              },
              staticOverrides: { byObject: {} },
            },
          },
        },
      }

      const result = await down(project)
      expect(result).toEqual(project)
    })

    it('handles project with no timeline', async () => {
      const project: NoodlesProjectJSON = {
        version: 13,
        nodes: [],
        edges: [],
        viewport: { x: 0, y: 0, zoom: 1 },
        timeline: {},
      }

      const result = await down(project)
      expect(result).toEqual(project)
    })
  })

  describe('round-trip', () => {
    it('preserves timeline data through up and down migrations', async () => {
      const project: NoodlesProjectJSON = {
        version: 12,
        nodes: [{ id: '/test', type: 'NumberOp', position: { x: 0, y: 0 }, data: {} }],
        edges: [],
        viewport: { x: 100, y: 200, zoom: 1.5 },
        timeline: {
          sheetsById: {
            Noodles: {
              sequence: {
                length: 15,
                subUnitsPerUnit: 60,
                tracksByObject: {
                  test: {
                    trackIdByPropPath: { value: 'track_1' },
                    trackData: {
                      track_1: {
                        type: 'BasicKeyframedTrack',
                        keyframes: [
                          {
                            id: 'kf_1',
                            position: 0,
                            connectedRight: true,
                            handles: [0, 0, 1, 1],
                            value: 0,
                          },
                          {
                            id: 'kf_2',
                            position: 5,
                            connectedRight: false,
                            handles: [0, 0, 1, 1],
                            value: 100,
                          },
                        ],
                      },
                    },
                  },
                },
              },
              staticOverrides: { byObject: {} },
            },
          },
        },
      }

      const afterUp = await up(project)
      const afterDown = await down(afterUp)

      // Should be identical to original (markers field removed)
      expect(afterDown).toEqual(project)
    })
  })
})

// Migration to remove MapStyleOp nodes and inline their value onto connected
// MaplibreBasemapOp inputs. The MapStyleOp was a pass-through node that only
// existed to expose a preset map style URL as a string output.

import type { NoodlesProjectJSON } from '../utils/serialization'

const CARTO_DARK = 'https://basemaps.cartocdn.com/gl/dark-matter-nolabels-gl-style/style.json'

export async function up(project: NoodlesProjectJSON): Promise<NoodlesProjectJSON> {
  const mapStyleNodes = project.nodes.filter(n => n.type === 'MapStyleOp')
  if (mapStyleNodes.length === 0) return project

  const mapStyleIds = new Set(mapStyleNodes.map(n => n.id))

  // Build a map of mapStyleOpId -> the style URL value it held
  const styleValues = new Map<string, string>()
  for (const node of mapStyleNodes) {
    const val = (node.data?.inputs as Record<string, unknown> | undefined)?.mapStyle
    styleValues.set(node.id, typeof val === 'string' ? val : CARTO_DARK)
  }

  // Find edges from MapStyleOp.out.mapStyle -> MaplibreBasemapOp.par.mapStyle
  // and record what value each target node should receive
  const targetValues = new Map<string, string>()
  for (const edge of project.edges) {
    if (mapStyleIds.has(edge.source) && edge.sourceHandle === 'out.mapStyle') {
      const styleUrl = styleValues.get(edge.source)
      if (styleUrl !== undefined) {
        targetValues.set(edge.target, styleUrl)
      }
    }
  }

  // Apply values to target nodes and remove MapStyleOp nodes + their edges
  const nodes = project.nodes
    .filter(n => !mapStyleIds.has(n.id))
    .map(node => {
      const val = targetValues.get(node.id)
      if (val === undefined) return node
      return {
        ...node,
        data: {
          ...node.data,
          inputs: {
            ...(node.data?.inputs as Record<string, unknown> | undefined),
            mapStyle: val,
          },
        },
      }
    })

  const edges = project.edges.filter(e => !mapStyleIds.has(e.source) && !mapStyleIds.has(e.target))

  return { ...project, nodes, edges }
}

export async function down(project: NoodlesProjectJSON): Promise<NoodlesProjectJSON> {
  // For each MaplibreBasemapOp with a mapStyle input value and no incoming edge
  // for par.mapStyle, recreate a MapStyleOp node and connecting edge
  const connectedTargets = new Set(
    project.edges.filter(e => e.targetHandle === 'par.mapStyle').map(e => e.target)
  )

  const newNodes = [...project.nodes]
  const newEdges = [...project.edges]

  for (const node of project.nodes) {
    if (node.type !== 'MaplibreBasemapOp') continue
    if (connectedTargets.has(node.id)) continue

    const val = (node.data?.inputs as Record<string, unknown> | undefined)?.mapStyle
    if (typeof val !== 'string') continue

    const mapStyleId = `${node.id}-map-style`
    newNodes.push({
      id: mapStyleId,
      type: 'MapStyleOp',
      position: { x: node.position.x - 320, y: node.position.y },
      data: { inputs: { mapStyle: val } },
    })

    newEdges.push({
      id: `${mapStyleId}.out.mapStyle->${node.id}.par.mapStyle`,
      source: mapStyleId,
      target: node.id,
      sourceHandle: 'out.mapStyle',
      targetHandle: 'par.mapStyle',
    })
  }

  // Remove mapStyle from MaplibreBasemapOp inputs where we just created a MapStyleOp
  const createdIds = new Set(newNodes.filter(n => n.type === 'MapStyleOp').map(n => n.id))
  const targetIds = new Set(newEdges.filter(e => createdIds.has(e.source)).map(e => e.target))

  const nodes = newNodes.map(node => {
    if (!targetIds.has(node.id)) return node
    const { mapStyle: _, ...restInputs } = (node.data?.inputs as Record<string, unknown>) ?? {}
    return {
      ...node,
      data: { ...node.data, inputs: restInputs },
    }
  })

  return { ...project, nodes, edges: newEdges }
}

