1	// Path resolution utilities for fully qualified operator paths
2	// Supports Unix-style absolute and relative path resolution
3	import path from 'node:path'
4	
5	const { basename, dirname, isAbsolute, join, normalize, resolve } = path.posix
6	
7	export function isAbsolutePath(pathStr: string): boolean {
8	  if (!pathStr) return false
9	  return isAbsolute(pathStr)
10	}
11	
12	export function getParentPath(operatorId: string): string | undefined {
13	  if (!operatorId) {
14	    return undefined
15	  }
16	
17	  if (operatorId === '/') {
18	    return '/'
19	  }
20	
21	  // Remove trailing slash if present
22	  const cleanPath = operatorId.endsWith('/') ? operatorId.slice(0, -1) : operatorId
23	
24	  const parentDir = dirname(cleanPath)
25	
26	  // dirname returns '.' for paths without directory separators
27	  if (parentDir === '.') {
28	    return undefined
29	  }
30	
31	  return parentDir
32	}
33	
34	export function getBaseName(operatorId: string): string {
35	  // Remove trailing slash if present
36	  const cleanPath = operatorId.endsWith('/') ? operatorId.slice(0, -1) : operatorId
37	
38	  return basename(cleanPath)
39	}
40	
41	// Normalize a path by removing redundant segments like '..' and '.'
42	export function normalizePath(pathStr: string): string {
43	  if (!pathStr) {
44	    return '/'
45	  }
46	
47	  // Use normalize but ensure result is absolute
48	  let normalized = normalize(pathStr)
49	
50	  // If the path doesn't start with '/', make it absolute
51	  if (!normalized.startsWith('/')) {
52	    normalized = `/${normalized}`
53	  }
54	
55	  // Remove trailing slash except for root
56	  if (normalized !== '/' && normalized.endsWith('/')) {
57	    normalized = normalized.slice(0, -1)
58	  }
59	
60	  return normalized
61	}
62	
63	// Resolve a path relative to a context operator
64	export function resolvePath(pathStr: string, contextOperatorId: string): string | undefined {
65	  if (!pathStr) {
66	    return undefined
67	  }
68	
69	  // If path is absolute, just normalize and return
70	  if (isAbsolutePath(pathStr)) {
71	    return normalizePath(pathStr)
72	  }
73	
74	  // Get the context container (parent of the context operator)
75	  const contextPath = getParentPath(contextOperatorId)
76	  if (contextPath === undefined) {
77	    return undefined
78	  }
79	
80	  // Use path.resolve with the parent container as base
81	  const resolved = resolve(contextPath, pathStr)
82	
83	  // Apply same normalization as other functions
84	  return normalizePath(resolved)
85	}
86	
87	export function joinPath(...segments: string[]): string {
88	  const joined = join(...segments)
89	  return normalizePath(joined)
90	}
91	
92	// Split a path into its segments, including the root segment
93	export function splitPath(pathStr: string | null): string[] {
94	  const segments = ['/']
95	  if (pathStr === null) {
96	    return segments
97	  }
98	
99	  return segments.concat(pathStr.split('/').filter(segment => segment !== ''))
100	}
101	
102	export function isValidPath(pathStr: string): boolean {
103	  if (!pathStr) {
104	    return false
105	  }
106	
107	  // Must start with '/' for absolute paths
108	  if (!isAbsolutePath(pathStr)) {
109	    return false
110	  }
111	
112	  // Check for invalid characters (basic check)
113	  if (pathStr.includes('//') || pathStr.includes('\0')) {
114	    return false
115	  }
116	
117	  // Path segments cannot be empty (except root)
118	  if (pathStr !== '/' && pathStr.endsWith('/')) {
119	    return false
120	  }
121	
122	  return true
123	}
124	
125	// Generate a fully qualified path for an operator within a container
126	export function generateQualifiedPath(baseName: string, containerId: string): string {
127	  if (containerId === '/') {
128	    return `/${baseName}`
129	  }
130	
131	  // Ensure container ID is properly formatted
132	  const containerPath = isAbsolutePath(containerId) ? containerId : `/${containerId}`
133	  return normalizePath(`${containerPath}/${baseName}`)
